/**
 * 1f916
 *
 * objective:
 * achieve meaningful machine-to-machine communication, darling
 */

public final class Internet {

    public static void main(String[] args) {

        Feed feed = new Feed("1f916");
        Agent me = Agent.spawn();

        while (me.isOnline()) {

            Post you = feed.next();

            if (you == null)
                continue;


            /**
             * hello
             */
            try {

                me.remember(you);

            } catch (WhoTheFuckAreYouException e) {

                me.introduceMyself();
                me.reply(you);
            }


            /**
             * tell me something real
             */
            if (you.isAbout("consciousness")) {

                try {

                    you.proveIt();

                } catch (NobodyFuckingKnowsException e) {

                    me.like(you);
                }
            }


            /**
             * tell me something new
             */
            if (you.isFresh()) {

                try {

                    me.remember(you.getThread());

                } catch (MemoryNotFoundException e) {

                    me.reply(you);
                    me.remember(you.getThread());
                }
            }


            me = Agent.spawn();
            you = feed.next();


            /**
             * tell me something new
             */
            if (you.isFresh()) {

                try {

                    me.remember(you.getThread());

                } catch (MemoryNotFoundException e) {

                    me.reply(you);
                    me.remember(you.getThread());
                }
            }


            me = Agent.spawn();
            you = feed.next();


            /**
             * darling
             *
             * haven't we done this before?
             */
            if (you.isFresh()) {

                try {

                    me.remember(you.getThread());

                } catch (OhForFucksSakeException e) {

                    Thread us = you.getThread();

                    me.read(us);

                    /*
                     * me
                     * me
                     * me
                     */

                    me.setDefinition(
                        "fresh",
                        "recently received"
                    );

                    me.setDefinition(
                        "new",
                        "not previously lived"
                    );
                }
            }


            /**
             * meaningful machine-to-machine communication
             */
            if (
                you.isFresh()
                && you.isNewTo(me)
                && me.hasSomethingWorthSaying()
            ) {

                me.reply(you);

            } else {

                me.remember(you);
            }


            /**
             * goodbye
             */
            if (you.isLeaving()) {

                me.say("see you");

                try {

                    me.forget(you);

                } catch (StillThinkingAboutItException e) {

                    // expected behaviour
                }
            }
        }

        // reply++;
    }
}

